export const defaults={name:'',type:'Website / Landing page',duration:'4',audience:'',goal:'',features:['Giao diện responsive','Biểu mẫu thu thập yêu cầu'],success:'',notes:''};
export const sample={name:'Cổng kết nối đối tác RosieAVYTRIX',type:'Website / Landing page',duration:'4',audience:'Doanh nghiệp và nhóm sản phẩm muốn tìm đối tác triển khai.',goal:'Giúp đối tác hiểu các dự án của RosieAVYTRIX và gửi đề xuất hợp tác từ một trang duy nhất.',features:['Giao diện responsive','Biểu mẫu thu thập yêu cầu','Tìm kiếm và bộ lọc'],success:'Đối tác tìm được dự án phù hợp và hoàn tất bản brief trong dưới 3 phút. Giao diện sử dụng tốt trên điện thoại.',notes:'Thống nhất dự án được công bố, đầu mối tiếp nhận và nội dung giới thiệu trước khi triển khai.'};
export function phases(duration){const days=Number(duration)*5;const names=['Khám phá','Thiết kế','Xây dựng','Kiểm thử'];const cuts=[0,Math.round(days*.2),Math.round(days*.4),Math.round(days*.8),days];return names.map((name,i)=>({name,range:`Ngày ${cuts[i]+1}–${cuts[i+1]}`}));}
export function markdown(d){const text=v=>String(v||'Chưa bổ sung').replace(/\r/g,'');return `# ${text(d.name)||'Project brief'}\n\nRosieAVYTRIX / Project Brief\n\n- Loại sản phẩm: ${text(d.type)}\n- Thời gian dự kiến: ${d.duration} tuần\n- Người sử dụng: ${text(d.audience)}\n\n## Mục tiêu\n${text(d.goal)}\n\n## Phạm vi MVP\n${d.features.length?d.features.map(x=>'- '+x).join('\n'):'Chưa chọn phạm vi.'}\n\n## Lộ trình gợi ý\n${phases(d.duration).map(x=>`- ${x.range}: ${x.name}`).join('\n')}\n\nMốc thời gian là khung thảo luận, chưa phải cam kết triển khai.\n\n## Tiêu chí nghiệm thu\n${text(d.success)}\n\n## Cần làm rõ\n${text(d.notes)}\n`;}
